def find_target_sum_ways(nums, target):
    n = len(nums)
    count = 0

    def backtrack(index, total):
        nonlocal count
        if index == n:
            if total == target:
                count += 1
            return
        backtrack(index + 1, total + nums[index])
        backtrack(index + 1, total - nums[index])

    backtrack(0, 0)
    return count

